COMMIT TRAN;
GO

SELECT cnicInvAccnt, cnicType, cnicGroup, LEN(cnicText) AS L, LEFT(cnicText, 80) AS txt
FROM test_sudz.cnInvCmm
WHERE cnicInvAccnt IN (82, 85) AND cnicType = 1 AND cnicGroup = 903
ORDER BY 1;
GO
